using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CMVerify {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit mode required");var h=R+"/SourceAssets/CoolingPumpMotorRepair";var data=JObject.Parse(File.ReadAllText(h+"/before.json"));var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var errors=new List<string>();var pumps=new List<object>();var meshes=new HashSet<Mesh>();int colliders=0;
 foreach(var row in data["rows"]){var root=ts.Single(x=>x.name==(string)row["name"]);if(Vector3.Distance(root.position,V(row["position"]))>.0001f||Vector3.Distance(root.localScale,V(row["localScale"]))>.0001f||Quaternion.Angle(root.localRotation,Quaternion.Euler(V(row["localEuler"])))>.001f)errors.Add("Root changed: "+root.name);
 foreach(var c in row["colliders"]){GlobalObjectId.TryParse((string)c["id"],out var id);var obj=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id);if(!obj||EditorJsonUtility.ToJson(obj)!=(string)c["json"])errors.Add("Collider changed: "+root.name);colliders++;}
 if((string)row["model"]!="BM_CoolingPump")continue;var rr=root.GetComponentsInChildren<MeshRenderer>().Where(r=>r.enabled&&r.name.StartsWith("Aligned_LOD")).OrderBy(r=>r.name).ToArray();if(rr.Length!=2){errors.Add("LOD count: "+root.name);continue;}float drift=Mathf.Max(Vector3.Distance(rr[0].bounds.min,V(row["min"])),Vector3.Distance(rr[0].bounds.max,V(row["max"])));if(drift>.002f)errors.Add("Bounds changed: "+root.name+" "+drift);if(Mathf.Abs(rr[0].bounds.min.y-root.position.y)>.001f)errors.Add("Ground: "+root.name);
 var lods=root.GetComponentsInChildren<LODGroup>(true);foreach(var r in rr){var m=r.GetComponent<MeshFilter>().sharedMesh;meshes.Add(m);if(m.subMeshCount!=r.sharedMaterials.Length||r.sharedMaterials.Any(a=>!a))errors.Add("Materials: "+root.name);if(lods.Count(g=>g.GetLODs().Any(l=>l.renderers.Contains(r)))!=1)errors.Add("LOD binding: "+root.name);}
 if(Quaternion.Angle(rr[0].transform.rotation,rr[1].transform.rotation)>.001f)errors.Add("LOD rotation: "+root.name);pumps.Add(new{name=root.name,boundsDriftMetres=drift,groundY=rr[0].bounds.min.y,materials=rr[0].sharedMaterials.Select(m=>m.name)});
 }
 var details=meshes.Select(m=>{if(m.vertexCount==0||m.triangles.Length==0||m.isReadable)errors.Add("Mesh: "+m.name);return new{name=m.name,vertices=m.vertexCount,triangles=m.triangles.Length/3,submeshes=m.subMeshCount,readable=m.isReadable};}).ToArray();var result=new{scene=s.path,placementsChecked=data["rows"].Count(),collidersChecked=colliders,pumps,meshes=details,errors};File.WriteAllText(h+"/validation.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{placements=data["rows"].Count(),colliders,pumps=pumps.Count,meshes=details,errors};}
}
